double dist_sq = std::numeric_limits<double>::max();
tree.nearest_point(p, CGAL::Closest_point_traits<Tree>::Distance_predicate(), 
                   [&dist_sq](const auto& primitive) {
                       double d = CGAL::squared_distance(p, primitive);
                       if (d < dist_sq) {
                           dist_sq = d;
                       }
                   });
return dist_sq;
